-- M38 (owner, 21 Nov 2026): an Approver was told "Next step — yours: approve" on planned-maintenance Work Order
-- FW-2026-0012, but found no Approve button: the job asked for a location mark, a Before photo and a contractor
-- quotation, which a planned task generated by the app does not have. Planned maintenance now works like this:
-- 1. Its Work Orders are approved as in-house work (the equipment, place and scope are already set by the plan;
--    contractor visits are under the service contract, so no quotation per visit). Existing open ones follow.
-- 2. The approval check skips the location mark and the Before photo for planned maintenance and the Daily round.
-- 3. They carry no reaction SLA clock (acknowledge / attend / fix); they are measured against their due date.
-- 4. (Owner, 21 Nov) "Our team" showed nobody: the page read memberships with the service key, which has no access to
--    facility_memberships. visible_facility_memberships() returns who is on staff (person, facility, role, and the
--    name, trade and work phone shown on Our team) for the
--    facilities the caller is on staff of; the Super-Administrator sees every facility. The Finance payment reminder
--    had the same flaw (it found no facility for anyone, so sent nothing); finance_reminder_facilities() fixes it.
-- 5. (Owner, 21:04) Daily round readings carry a normal range (low and/or high) and a short guide, so the Technician
--    can judge OK / Not OK. A reading outside the range may still be ticked OK only with a reason. Each result keeps
--    the range that applied when it was recorded. Tick-only items can carry a guide too (what "OK" looks like).
-- 6. (Owner, 22 Nov) The Facility Manager may open and manage the emergency on-call roster.
begin;

create or replace function public.planned_work_in_house()
returns trigger language plpgsql set search_path = pg_catalog as $function$
begin
  if new.pm_occurrence_id is not null or new.daily_round_date is not null then new.in_house_work := true; end if;
  return new;
end;
$function$;
revoke all on function public.planned_work_in_house() from public, anon, authenticated, service_role;
create trigger planned_work_in_house before insert on public.work_orders for each row execute function public.planned_work_in_house();

update public.work_orders set in_house_work = true, updated_at = pg_catalog.now()
where pm_occurrence_id is not null and not in_house_work and status in ('draft','submitted','approved');

CREATE OR REPLACE FUNCTION public.work_order_approval_summary(p_work_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare w public.work_orders%rowtype; control public.work_order_financial_controls%rowtype; required_count integer; collected_count integer;
  amount numeric; level text; authority jsonb; missing jsonb:='[]'::jsonb;
begin
  if not public.release1_work_order_visible(p_work_order_id) then
    return public.work_order_result_error('ACCESS_DENIED','This Work Order is outside your permitted scope.'); end if;
  select * into w from public.work_orders where id=p_work_order_id;
  select * into control from public.work_order_financial_controls where work_order_id=w.id;
  select minimum_quotations into required_count from public.commercial_approval_rules where id=control.rule_id;
  select pg_catalog.count(distinct vendor_id) into collected_count from public.contractor_quotations where work_order_id=w.id and status in ('submitted','approved');
  amount:=control.quoted_cost;
  if pg_catalog.length(pg_catalog.btrim(coalesce(w.description,'')))<10 then missing:=missing||'"Reason the work is needed"'::jsonb; end if;
  -- D-15: a due date earlier than the submission date is refused by work_orders_due_date_check.
  if w.status='draft' and w.due_date is not null and w.pm_occurrence_id is null and w.due_date<(pg_catalog.now())::date then missing:=missing||'"Due date has passed — update the due date"'::jsonb; end if;
  if w.assigned_technician_id is null then missing:=missing||'"Field-witness Technician"'::jsonb; end if;
  -- M38: planned maintenance and the Daily round know their equipment and place; no location mark or Before photo.
  if not w.emergency_work and w.pm_occurrence_id is null and w.daily_round_date is null then
    if not public.work_order_location_marked(w.id) then missing:=missing||'"Location marked on the layout plan"'::jsonb; end if;
    if not public.work_order_before_evidence_present(w.id) then missing:=missing||'"Before photo, video or voice note of the site"'::jsonb; end if;
  end if;
  if public.work_order_endorsement_missing(w.id,'submission') then missing:=missing||'"Second Technician endorsement"'::jsonb; end if;
  if not w.emergency_work and not w.in_house_work then
    if collected_count<coalesce(required_count,1) then missing:=missing||pg_catalog.to_jsonb(pg_catalog.format('Quotations: %s of %s submitted',collected_count,coalesce(required_count,1))); end if;
    if control.work_order_id is null or control.cost_status<>'recommended' or amount is null then missing:=missing||'"Recommended contractor quotation"'::jsonb; end if;
  end if;
  select l.role into level from public.work_order_approval_limits l join public.work_order_approval_limit_policy p on p.version_id=l.version_id
    where amount is not null and (l.maximum_amount is null or l.maximum_amount>=amount)
    order by l.maximum_amount nulls last, case l.role when 'approver' then 1 when 'supervisor' then 2 when 'facility_manager' then 3 else 4 end limit 1;
  if w.status='submitted' and (amount is not null or w.in_house_work) then authority:=public.work_order_approval_authority(w.id,coalesce(amount,0),null); end if;
  return pg_catalog.jsonb_build_object('ok',true,'status',w.status,'emergency_work',w.emergency_work,'in_house_work',w.in_house_work,
    'quoted_cost',amount,'approved_budget',control.approved_budget,'cost_status',control.cost_status,
    'required_quotations',coalesce(required_count,1),'collected_quotations',collected_count,
    'missing_requirements',missing,'ready',pg_catalog.jsonb_array_length(missing)=0,
    'lowest_authority',level,'board_approval_required',coalesce(amount,0)>1000000,
    'can_approve',w.status='submitted' and (amount is not null or w.in_house_work) and authority is null,
    'approval_blocker',authority->>'code','approval_blocker_message',authority->>'message');
end;$function$;

create or replace function public.attach_approved_sla_clock()
returns trigger language plpgsql set search_path = pg_catalog as $fn$
declare selected_rule public.sla_rules; start_time timestamptz := coalesce(new.submitted_at, new.created_at, pg_catalog.now());
begin
  -- M36: the Daily round is routine; it has no SLA clock.
  -- M36/M38: the Daily round and planned maintenance are measured against their due date, not a reaction SLA.
  if new.daily_round_date is not null or new.pm_occurrence_id is not null then return new; end if;
  selected_rule := public.sla_rule_for(new.facility_id, new.sla_service_category_id, new.priority, start_time);
  if selected_rule.id is not null then
    insert into public.work_order_sla_clocks(work_order_id, sla_rule_id, started_at, acknowledgement_deadline, response_deadline, attendance_deadline, make_safe_deadline, rectification_deadline)
    values (new.id, selected_rule.id, start_time,
      case when selected_rule.acknowledgement_minutes is not null then start_time + pg_catalog.make_interval(mins => selected_rule.acknowledgement_minutes) end,
      case when selected_rule.response_minutes is not null then start_time + pg_catalog.make_interval(mins => selected_rule.response_minutes) end,
      case when selected_rule.attendance_minutes is not null then start_time + pg_catalog.make_interval(mins => selected_rule.attendance_minutes) end,
      case when selected_rule.make_safe_minutes is not null then start_time + pg_catalog.make_interval(mins => selected_rule.make_safe_minutes) end,
      start_time + pg_catalog.make_interval(mins => selected_rule.rectification_minutes))
    on conflict (work_order_id) do nothing;
  end if;
  return new;
end;$fn$;

create or replace function public.visible_facility_memberships()
returns table(profile_id uuid, facility_id uuid, membership_role text, display_name text, trade_discipline text, contact_number text)
language sql stable security definer set search_path = pg_catalog as $function$
  select m.profile_id, m.facility_id, m.membership_role, p.display_name, p.trade_discipline, p.contact_number
  from public.facility_memberships m join public.profiles p on p.id = m.profile_id and p.is_active and p.deleted_at is null
  where public.pilot_account_ready(auth.uid()) and m.active
    and m.effective_from <= pg_catalog.now() and (m.effective_to is null or m.effective_to > pg_catalog.now())
    and (public.current_user_role() = 'administrator' or exists(
      select 1 from public.facility_memberships mine where mine.facility_id = m.facility_id and mine.profile_id = auth.uid() and mine.active
        and mine.effective_from <= pg_catalog.now() and (mine.effective_to is null or mine.effective_to > pg_catalog.now())))
$function$;
revoke all on function public.visible_facility_memberships() from public, anon, service_role;
grant execute on function public.visible_facility_memberships() to authenticated;

-- The Finance payment reminder runs on the server without a signed-in person: it may read only which facilities each
-- Finance person currently belongs to.
create or replace function public.finance_reminder_facilities(p_profile_ids uuid[])
returns table(profile_id uuid, facility_id uuid)
language sql stable security definer set search_path = pg_catalog as $function$
  select m.profile_id, m.facility_id from public.facility_memberships m
  where m.profile_id = any(coalesce(p_profile_ids, '{}'::uuid[])) and m.membership_role = 'finance' and m.active
    and m.effective_from <= pg_catalog.now() and (m.effective_to is null or m.effective_to > pg_catalog.now())
$function$;
revoke all on function public.finance_reminder_facilities(uuid[]) from public, anon, authenticated;
grant execute on function public.finance_reminder_facilities(uuid[]) to service_role;


-- 5. Normal ranges for Daily round readings ---------------------------------------------------------------------------
alter table public.daily_round_items
  add column reading_min numeric, add column reading_max numeric,
  add column reading_guide text check (reading_guide is null or pg_catalog.length(reading_guide) between 2 and 160),
  add constraint daily_round_items_range_check check (reading_min is null or reading_max is null or reading_min <= reading_max);
alter table public.daily_round_results
  add column reading_min numeric, add column reading_max numeric, add column out_of_range boolean;
comment on column public.daily_round_items.reading_min is 'M38: lowest normal reading (null = no low limit).';
comment on column public.daily_round_items.reading_max is 'M38: highest normal reading (null = no high limit).';
comment on column public.daily_round_items.reading_guide is 'M38: short guide shown with the item (reading or tick), e.g. "Not above the nameplate full-load current".';

-- "7.5", "-20", "−20" (minus sign) or "7,5" → number; anything else → null.
create or replace function public.daily_round_number(p_reading text)
returns numeric language sql immutable set search_path = pg_catalog as $function$
  select case when pg_catalog.btrim(coalesce(p_reading, '')) ~ '^[-−+]?[0-9]+([.,][0-9]+)?$'
    then pg_catalog.replace(pg_catalog.replace(pg_catalog.btrim(p_reading), '−', '-'), ',', '.')::numeric end
$function$;

-- "6 – 8 °C", "at most 500 ppb", "at least 10 Pa".
create or replace function public.daily_round_range_text(p_min numeric, p_max numeric, p_unit text)
returns text language sql immutable set search_path = pg_catalog as $function$
  select case
    when p_min is not null and p_max is not null then pg_catalog.trim_scale(p_min)::text || ' – ' || pg_catalog.trim_scale(p_max)::text || ' ' || coalesce(p_unit, '')
    when p_max is not null then 'at most ' || pg_catalog.trim_scale(p_max)::text || ' ' || coalesce(p_unit, '')
    when p_min is not null then 'at least ' || pg_catalog.trim_scale(p_min)::text || ' ' || coalesce(p_unit, '')
  end
$function$;

revoke all on function public.daily_round_number(text), public.daily_round_range_text(numeric, numeric, text) from public, anon, service_role;
grant execute on function public.daily_round_number(text), public.daily_round_range_text(numeric, numeric, text) to authenticated;

drop function public.save_daily_round_item(uuid, uuid, text, text, integer, boolean);
create function public.save_daily_round_item(p_item_id uuid, p_check_id uuid, p_label text, p_reading_unit text, p_position integer, p_active boolean,
  p_reading_min numeric default null, p_reading_max numeric default null, p_reading_guide text default null)
returns jsonb language plpgsql security definer set search_path = pg_catalog as $function$
declare actor jsonb := public.work_order_actor(); v_check uuid; v_facility uuid; v_id uuid;
  v_unit text := nullif(pg_catalog.btrim(coalesce(p_reading_unit, '')), '');
  v_guide text := nullif(pg_catalog.btrim(coalesce(p_reading_guide, '')), '');
  v_min numeric; v_max numeric;
begin
  v_check := coalesce((select check_id from public.daily_round_items where id = p_item_id), p_check_id);
  select facility_id into v_facility from public.daily_round_checks where id = v_check;
  if actor is null or v_facility is null or not public.daily_round_editor(v_facility) then return public.pm_result_error('ACCESS_DENIED', 'You cannot change this Daily round.'); end if;
  -- A range only applies to an item with a reading; a guide may go with any item.
  v_min := case when v_unit is not null then p_reading_min end;
  v_max := case when v_unit is not null then p_reading_max end;
  if v_min is not null and v_max is not null and v_min > v_max then return public.pm_result_error('VALIDATION_ERROR', 'The low limit must not be above the high limit.'); end if;
  if p_item_id is null then
    insert into public.daily_round_items(check_id, position, label, reading_unit, reading_min, reading_max, reading_guide, active, created_by)
    values (v_check, coalesce(p_position, 100), pg_catalog.btrim(p_label), v_unit, v_min, v_max, v_guide, coalesce(p_active, true), (actor ->> 'id')::uuid)
    returning id into v_id;
  else
    update public.daily_round_items set label = pg_catalog.btrim(p_label), reading_unit = v_unit, reading_min = v_min, reading_max = v_max, reading_guide = v_guide,
      position = coalesce(p_position, position), active = coalesce(p_active, active)
    where id = p_item_id returning id into v_id;
  end if;
  insert into public.activity_logs(user_id, action, actor, note) values ((actor ->> 'id')::uuid, 'daily_round_item_saved', coalesce(actor ->> 'display_name', actor ->> 'name'),
    pg_catalog.jsonb_build_object('item_id', v_id, 'check_id', v_check, 'label', p_label, 'active', p_active, 'unit', v_unit, 'min', v_min, 'max', v_max, 'guide', v_guide)::text);
  return pg_catalog.jsonb_build_object('ok', true, 'id', v_id);
exception when check_violation then return public.pm_result_error('VALIDATION_ERROR', 'Give the item 2 to 300 characters, a unit of up to 20 and a guide of up to 160.');
end;
$function$;
revoke all on function public.save_daily_round_item(uuid, uuid, text, text, integer, boolean, numeric, numeric, text) from public, anon, service_role;
grant execute on function public.save_daily_round_item(uuid, uuid, text, text, integer, boolean, numeric, numeric, text) to authenticated;

create or replace function public.record_daily_round_item(p_work_order_id uuid, p_item_id uuid, p_ok boolean, p_reading text, p_note text)
returns jsonb language plpgsql security definer set search_path = pg_catalog as $function$
declare actor jsonb := public.work_order_actor(); w public.work_orders; i public.daily_round_items; v_num numeric; v_out boolean;
begin
  select * into w from public.work_orders where id = p_work_order_id for update;
  if w.id is null or w.daily_round_date is null then return public.pm_result_error('NOT_FOUND', 'Daily round not found.'); end if;
  if actor is null or not public.daily_round_recorder(w.id) then return public.pm_result_error('ACCESS_DENIED', 'The Technician of this round records it.'); end if;
  if w.status in ('closed','cancelled','reviewed','completed') then return public.pm_result_error('ROUND_CLOSED', 'This round is already completed.'); end if;
  select it.* into i from public.daily_round_items it join public.daily_round_checks c on c.id = it.check_id where it.id = p_item_id and c.facility_id = w.facility_id;
  if i.id is null then return public.pm_result_error('NOT_FOUND', 'Item not found in this round.'); end if;
  if p_ok is null then return public.pm_result_error('VALIDATION_ERROR', 'Choose OK or Not OK.'); end if;
  if i.reading_unit is not null and pg_catalog.length(pg_catalog.btrim(coalesce(p_reading, ''))) = 0 then return public.pm_result_error('VALIDATION_ERROR', 'Enter the reading.'); end if;
  if i.reading_min is not null or i.reading_max is not null then
    v_num := public.daily_round_number(p_reading);
    if v_num is null then return public.pm_result_error('VALIDATION_ERROR', 'Enter the reading as a number, e.g. 7.5.'); end if;
    v_out := (i.reading_min is not null and v_num < i.reading_min) or (i.reading_max is not null and v_num > i.reading_max);
    if v_out and p_ok and pg_catalog.length(pg_catalog.btrim(coalesce(p_note, ''))) < 3 then
      return public.pm_result_error('OUT_OF_RANGE', 'The reading is outside the normal range (' || public.daily_round_range_text(i.reading_min, i.reading_max, i.reading_unit)
        || '). Choose Not OK, or say why it is still OK.'); end if;
  end if;
  if not p_ok and pg_catalog.length(pg_catalog.btrim(coalesce(p_note, ''))) < 3 then return public.pm_result_error('VALIDATION_ERROR', 'Say what is wrong.'); end if;
  insert into public.daily_round_results(work_order_id, item_id, ok, reading, note, recorded_by, reading_min, reading_max, out_of_range)
  values (w.id, p_item_id, p_ok, nullif(pg_catalog.btrim(coalesce(p_reading, '')), ''), nullif(pg_catalog.btrim(coalesce(p_note, '')), ''), (actor ->> 'id')::uuid, i.reading_min, i.reading_max, v_out)
  on conflict (work_order_id, item_id) do update set ok = excluded.ok, reading = excluded.reading, note = excluded.note, recorded_by = excluded.recorded_by, recorded_at = pg_catalog.now(),
    reading_min = excluded.reading_min, reading_max = excluded.reading_max, out_of_range = excluded.out_of_range;
  if w.status in ('approved','assigned') then
    update public.work_orders set status = 'in_progress', started_at = coalesce(started_at, pg_catalog.now()), actual_work_started_at = coalesce(actual_work_started_at, pg_catalog.now()),
      updated_at = pg_catalog.now() where id = w.id;
    insert into public.activity_logs(user_id, work_order_id, action, from_status, to_status, actor, note)
    values ((actor ->> 'id')::uuid, w.id, 'daily_round_started', w.status, 'in_progress', coalesce(actor ->> 'display_name', actor ->> 'name'), '{}');
  end if;
  return pg_catalog.jsonb_build_object('ok', true, 'out_of_range', coalesce(v_out, false));
end;
$function$;


-- 6. (Owner, 22 Nov 2026) The Facility Manager manages the emergency on-call roster, like the Supervisor
--    (functions from 0015 restated with facility_manager added; nothing else changes).
create or replace function public.get_emergency_roster()
returns table (
  id uuid, profile_id uuid, profile_display_name text, profile_role text,
  team_id uuid, team_name text, receive_emergency_alerts boolean,
  sms_enabled boolean, whatsapp_enabled boolean, email_enabled boolean,
  escalation_order integer, active_from timestamptz, active_to timestamptz,
  incident_type text, active boolean, created_at timestamptz, updated_at timestamptz
)
language sql stable security definer set search_path = public, pg_temp as $fn$
  select r.id,r.profile_id,p.display_name,p.role,r.team_id,t.name,
    r.receive_emergency_alerts,r.sms_enabled,r.whatsapp_enabled,r.email_enabled,
    r.escalation_order,r.active_from,r.active_to,r.incident_type,r.active,r.created_at,r.updated_at
  from public.emergency_response_roster r
  left join public.profiles p on p.id=r.profile_id
  left join public.maintenance_teams t on t.id=r.team_id
  where auth.uid() is not null and public.current_user_role() in ('approver','supervisor','facility_manager','administrator')
  order by r.active desc,r.escalation_order,r.created_at
$fn$;

create or replace function public.get_emergency_response_options()
returns table (target_type text, target_id uuid, display_name text, role text)
language sql stable security definer set search_path = public, pg_temp as $fn$
  select 'technician',p.id,p.display_name,p.role from public.profiles p
  where auth.uid() is not null and public.current_user_role() in ('supervisor','facility_manager','administrator')
    and p.role='technician' and p.is_active and p.deleted_at is null
  union all
  select 'team',t.id,t.name,null from public.maintenance_teams t
  where auth.uid() is not null and public.current_user_role() in ('supervisor','facility_manager','administrator')
    and t.is_active and t.deleted_at is null
$fn$;

create or replace function public.upsert_emergency_roster(p_roster_id uuid,p_payload jsonb)
returns jsonb language plpgsql security definer set search_path = public, pg_temp as $fn$
declare actor_role text:=public.current_user_role(); target_profile uuid; target_team uuid;
  start_at timestamptz; end_at timestamptz; incident_category text; ranking integer; result public.emergency_response_roster;
begin
  if auth.uid() is null then return public.incident_result_error('AUTHENTICATION_REQUIRED','Authentication is required.'); end if;
  if actor_role not in ('supervisor','facility_manager','administrator') then return public.incident_result_error('ACCESS_DENIED','Roster management permission is required.'); end if;
  target_profile:=nullif(p_payload->>'profile_id','')::uuid; target_team:=nullif(p_payload->>'team_id','')::uuid;
  if (target_profile is null)=(target_team is null) then return public.incident_result_error('VALIDATION_ERROR','Select one Technician or maintenance team.'); end if;
  if target_profile is not null and not exists(select 1 from public.profiles where id=target_profile and role='technician' and is_active and deleted_at is null) then return public.incident_result_error('INVALID_ASSIGNMENT','Select an active Technician.'); end if;
  if target_team is not null and not exists(select 1 from public.maintenance_teams where id=target_team and is_active and deleted_at is null) then return public.incident_result_error('INVALID_ASSIGNMENT','Select an active maintenance team.'); end if;
  start_at:=nullif(p_payload->>'active_from','')::timestamptz; end_at:=nullif(p_payload->>'active_to','')::timestamptz;
  if start_at is not null and end_at is not null and end_at<=start_at then return public.incident_result_error('VALIDATION_ERROR','Effective end must be after effective start.'); end if;
  incident_category:=nullif(pg_catalog.lower(p_payload->>'incident_type'),'');
  if incident_category is not null and incident_category not in ('lift_entrapment','fire','flood','major_water_leak','electrical_failure','gas_leak','chemical_spill','medical_emergency','security','other') then return public.incident_result_error('VALIDATION_ERROR','Incident type is invalid.'); end if;
  ranking:=coalesce((p_payload->>'escalation_order')::integer,100); if ranking<0 then return public.incident_result_error('VALIDATION_ERROR','Escalation order must not be negative.'); end if;
  if coalesce((p_payload->>'active')::boolean,true) and exists(select 1 from public.emergency_response_roster r where r.id is distinct from p_roster_id and r.active and r.escalation_order=ranking and r.incident_type is not distinct from incident_category and r.profile_id is not distinct from target_profile and r.team_id is not distinct from target_team and tstzrange(coalesce(r.active_from,'-infinity'),coalesce(r.active_to,'infinity'),'[)') && tstzrange(coalesce(start_at,'-infinity'),coalesce(end_at,'infinity'),'[)')) then return public.incident_result_error('DUPLICATE_ROSTER','An overlapping active roster entry already exists for this target and ranking.'); end if;
  if p_roster_id is null then
    insert into public.emergency_response_roster(profile_id,team_id,receive_emergency_alerts,sms_enabled,whatsapp_enabled,email_enabled,escalation_order,active_from,active_to,incident_type,active,created_by)
    values(target_profile,target_team,coalesce((p_payload->>'receive_emergency_alerts')::boolean,true),coalesce((p_payload->>'sms_enabled')::boolean,true),coalesce((p_payload->>'whatsapp_enabled')::boolean,true),false,ranking,start_at,end_at,incident_category,coalesce((p_payload->>'active')::boolean,true),auth.uid()) returning * into result;
  else
    update public.emergency_response_roster set profile_id=target_profile,team_id=target_team,receive_emergency_alerts=coalesce((p_payload->>'receive_emergency_alerts')::boolean,true),sms_enabled=coalesce((p_payload->>'sms_enabled')::boolean,true),whatsapp_enabled=coalesce((p_payload->>'whatsapp_enabled')::boolean,true),email_enabled=false,escalation_order=ranking,active_from=start_at,active_to=end_at,incident_type=incident_category,active=coalesce((p_payload->>'active')::boolean,true)
    where id=p_roster_id returning * into result;
    if result.id is null then return public.incident_result_error('NOT_FOUND','Roster entry was not found.'); end if;
  end if;
  return pg_catalog.jsonb_build_object('ok',true,'roster',pg_catalog.to_jsonb(result));
exception when invalid_text_representation or datetime_field_overflow then return public.incident_result_error('VALIDATION_ERROR','Roster values are invalid.');
when others then return public.incident_result_error('INTERNAL_ERROR','The roster entry could not be saved.'); end;
$fn$;

create or replace function public.set_emergency_roster_active(p_roster_id uuid,p_active boolean)
returns jsonb language plpgsql security definer set search_path = public, pg_temp as $fn$
declare result public.emergency_response_roster;
begin
  if auth.uid() is null then return public.incident_result_error('AUTHENTICATION_REQUIRED','Authentication is required.'); end if;
  if public.current_user_role() not in ('supervisor','facility_manager','administrator') then return public.incident_result_error('ACCESS_DENIED','Roster management permission is required.'); end if;
  update public.emergency_response_roster set active=p_active where id=p_roster_id returning * into result;
  if result.id is null then return public.incident_result_error('NOT_FOUND','Roster entry was not found.'); end if;
  return pg_catalog.jsonb_build_object('ok',true,'roster',pg_catalog.to_jsonb(result));
exception when others then return public.incident_result_error('INTERNAL_ERROR','The roster entry could not be updated.'); end;
$fn$;

revoke all on function public.get_emergency_roster(), public.get_emergency_response_options(), public.upsert_emergency_roster(uuid,jsonb), public.set_emergency_roster_active(uuid,boolean) from public, anon, service_role;
grant execute on function public.get_emergency_roster(), public.get_emergency_response_options(), public.upsert_emergency_roster(uuid,jsonb), public.set_emergency_roster_active(uuid,boolean) to authenticated;
drop policy if exists emergency_roster_authenticated_read on public.emergency_response_roster;
create policy emergency_roster_authenticated_read on public.emergency_response_roster for select to authenticated using (
  public.pilot_account_ready(auth.uid()) and (
    public.current_user_role() in ('supervisor','facility_manager','administrator') or profile_id = auth.uid()
  )
);

commit;
